"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import Link from "next/link";
import type { ReservationView } from "@/lib/present";
import { api } from "./api";
import { Button, Card, inputClass, StatusBadge } from "./ui";

type Result = { result: string; message: string; checkedIn: boolean; reservation: ReservationView | null };

const LOOK: Record<string, { title: string; tone: string }> = {
  valid: { title: "Valid", tone: "bg-mint-soft ring-mint/50" },
  done: { title: "Checked in", tone: "bg-mint-soft ring-mint/50" },
  already_checked_in: { title: "Already checked in", tone: "bg-amber-soft ring-amber/40" },
  too_early: { title: "Too early", tone: "bg-amber-soft ring-amber/40" },
  expired: { title: "Late or expired", tone: "bg-amber-soft ring-amber/40" },
  not_confirmed: { title: "Not confirmed yet", tone: "bg-amber-soft ring-amber/40" },
  cancelled: { title: "Cancelled", tone: "bg-rose-soft ring-rose/40" },
  invalid: { title: "Not found or invalid", tone: "bg-rose-soft ring-rose/40" },
};

type Detector = { detect(src: CanvasImageSource): Promise<{ rawValue: string }[]> };

export function CheckInDesk({ businessId, slug, today }: { businessId: string; slug: string; today: string }) {
  const base = `/api/b/${businessId}`;
  const [result, setResult] = useState<Result | null>(null);
  const [via, setVia] = useState<{ code?: string; reservationId?: string }>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [camera, setCamera] = useState<"off" | "starting" | "on" | "blocked" | "unsupported">("off");
  const [query, setQuery] = useState("");
  const [matches, setMatches] = useState<ReservationView[] | null>(null);
  const [code, setCode] = useState("");
  const video = useRef<HTMLVideoElement>(null);
  const stream = useRef<MediaStream | null>(null);
  const paused = useRef(false);
  const lastScan = useRef({ text: "", at: 0 });

  const verify = useCallback(async (payload: { code?: string; reservationId?: string }, commit = false, override = false) => {
    setBusy(true); setError("");
    try {
      const r = await api<Result>(`${base}/checkin`, { body: { ...payload, commit, override } });
      setVia(payload);
      setResult(commit && r.checkedIn ? { ...r, result: "done" } : r);
      paused.current = true; // hold the camera while staff read the result
    } catch (e) { setError((e as Error).message); }
    finally { setBusy(false); }
  }, [base]);

  const stopCamera = useCallback(() => {
    stream.current?.getTracks().forEach((t) => t.stop());
    stream.current = null;
    setCamera("off");
  }, []);

  async function startCamera() {
    setError("");
    if (!navigator.mediaDevices?.getUserMedia) return setCamera("unsupported");
    setCamera("starting");
    try {
      const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: "environment" }, width: { ideal: 1280 } }, audio: false });
      stream.current = s;
      setCamera("on");
    } catch { setCamera("blocked"); }
  }

  // Scan loop: the browser's built-in detector when it exists, otherwise a JavaScript decoder.
  useEffect(() => {
    if (camera !== "on" || !video.current || !stream.current) return;
    const v = video.current;
    v.srcObject = stream.current;
    void v.play().catch(() => {});
    let stop = false;
    let timer: ReturnType<typeof setTimeout>;
    const canvas = document.createElement("canvas");
    const ctx2d = canvas.getContext("2d", { willReadFrequently: true });
    let detector: Detector | null = null;
    const BD = (window as unknown as { BarcodeDetector?: new (o: { formats: string[] }) => Detector }).BarcodeDetector;
    if (BD) { try { detector = new BD({ formats: ["qr_code"] }); } catch { detector = null; } }
    let jsqr: typeof import("jsqr").default | null = null;

    const tick = async () => {
      if (stop) return;
      try {
        if (!paused.current && v.readyState >= 2 && v.videoWidth > 0) {
          let text = "";
          if (detector) {
            try { text = (await detector.detect(v))[0]?.rawValue ?? ""; } catch { detector = null; }
          }
          if (!text && !detector && ctx2d) {
            if (!jsqr) jsqr = (await import("jsqr")).default;
            const scale = Math.min(1, 800 / v.videoWidth);
            canvas.width = Math.round(v.videoWidth * scale); canvas.height = Math.round(v.videoHeight * scale);
            ctx2d.drawImage(v, 0, 0, canvas.width, canvas.height);
            const img = ctx2d.getImageData(0, 0, canvas.width, canvas.height);
            text = jsqr(img.data, img.width, img.height, { inversionAttempts: "dontInvert" })?.data ?? "";
          }
          const now = Date.now();
          if (text && !(text === lastScan.current.text && now - lastScan.current.at < 4000)) {
            lastScan.current = { text, at: now };
            await verify({ code: text.slice(0, 400) });
          }
        }
      } finally { if (!stop) timer = setTimeout(tick, 180); }
    };
    void tick();
    return () => { stop = true; clearTimeout(timer); };
  }, [camera, verify]);

  useEffect(() => () => { stream.current?.getTracks().forEach((t) => t.stop()); }, []);

  async function search(e: React.FormEvent) {
    e.preventDefault();
    const term = query.trim();
    if (term.length < 2) return;
    setBusy(true); setError(""); setResult(null);
    try {
      // Look around today first; staff can use the full list for other dates.
      const r = await api<{ reservations: ReservationView[] }>(`${base}/reservations?q=${encodeURIComponent(term)}&from=${today}&to=${today}&limit=20`);
      setMatches(r.reservations);
    } catch (err) { setError((err as Error).message); }
    finally { setBusy(false); }
  }

  function next() { setResult(null); setVia({}); setMatches(null); setQuery(""); setCode(""); paused.current = false; lastScan.current = { text: "", at: 0 }; }

  const look = result ? LOOK[result.result] ?? LOOK.invalid : null;
  const r = result?.reservation;

  return (
    <div className="space-y-4">
      {result && look && (
        <div className={`pop rounded-3xl p-5 ring-2 ${look.tone}`} role="status" aria-live="assertive" data-testid="verify-result" data-result={result.result}>
          <p className="font-display text-3xl font-extrabold">{look.title}</p>
          <p className="mt-1 text-[17px] text-ink-soft">{result.message}</p>
          {r && (
            <div className="mt-4 rounded-2xl bg-white p-4 ring-1 ring-line">
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="truncate text-xl font-bold">{r.customerName}</p>
                  <p className="text-ink-soft"><span className="font-display font-bold tabular">{r.time}</span>, {r.partySize} {r.partySize === 1 ? "guest" : "guests"}, {r.resource}</p>
                  <p className="text-[15px] text-muted">Reference {r.reference}{r.date !== today ? `, ${r.date}` : ""}</p>
                  {r.notes && <p className="mt-1 text-[15px] text-amber">Note: {r.notes}</p>}
                </div>
                <StatusBadge status={r.status} />
              </div>
            </div>
          )}
          <div className="mt-4 flex flex-wrap gap-2">
            {result.result === "valid" && <Button variant="mint" disabled={busy} className="min-h-14 flex-1 text-lg" data-testid="confirm-checkin" onClick={() => verify(via, true)}>Check in</Button>}
            {(result.result === "too_early" || result.result === "expired") && r?.status === "confirmed" && (
              <Button variant="quiet" disabled={busy} onClick={() => verify(via, true, true)}>Check in anyway</Button>
            )}
            <Button variant={result.result === "valid" ? "quiet" : "primary"} disabled={busy} className="min-h-14 flex-1" onClick={next}>{result.result === "valid" ? "Cancel" : "Next guest"}</Button>
            {r && <Link href={`/app/${slug}/reservations/${r.id}`} className="inline-flex min-h-14 items-center rounded-xl px-4 font-semibold ring-1 ring-line hover:bg-white">Details</Link>}
          </div>
        </div>
      )}
      {error && <p role="alert" className="rounded-xl bg-rose-soft px-4 py-3 text-rose">{error}</p>}

      <Card className={`overflow-hidden ${result ? "hidden" : ""}`}>
        {camera === "on" || camera === "starting" ? (
          <div className="relative bg-ink">
            <video ref={video} playsInline muted className="aspect-square w-full object-cover" aria-label="Camera preview" />
            <div className="pointer-events-none absolute inset-[14%] rounded-3xl ring-4 ring-white/80" aria-hidden="true" />
            <div className="absolute inset-x-0 bottom-0 flex items-center justify-between bg-ink/70 px-4 py-2.5 text-white">
              <span>{camera === "starting" ? "Starting camera…" : "Point at the ticket's QR code"}</span>
              <button type="button" className="rounded-lg px-3 py-1.5 font-semibold ring-1 ring-white/50" onClick={stopCamera}>Stop</button>
            </div>
          </div>
        ) : (
          <div className="p-5 text-center">
            <Button className="min-h-14 w-full text-lg" variant="mint" onClick={startCamera} data-testid="start-camera">Scan a ticket</Button>
            {camera === "blocked" && <p className="mt-3 text-[15px] text-rose">The camera could not be opened. Allow camera access for this site in your browser, or look the guest up below.</p>}
            {camera === "unsupported" && <p className="mt-3 text-[15px] text-rose">This browser cannot use the camera here (it needs a secure https address). Look the guest up below.</p>}
          </div>
        )}
      </Card>

      <Card className={`space-y-4 p-5 ${result ? "hidden" : ""}`}>
        <form onSubmit={search}>
          <label htmlFor="lookup" className="mb-1.5 block text-lg font-bold">Find today&apos;s guest</label>
          <div className="flex gap-2">
            <input id="lookup" className={inputClass} value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Name, reference or phone" autoComplete="off" />
            <Button type="submit" disabled={busy || query.trim().length < 2}>Find</Button>
          </div>
        </form>
        {matches && (matches.length === 0 ? (
          <p className="text-ink-soft">No reservation today matches “{query}”. <Link className="font-semibold text-brand" href={`/app/${slug}/reservations?q=${encodeURIComponent(query)}`}>Search all dates</Link></p>
        ) : (
          <ul className="divide-y divide-line rounded-xl ring-1 ring-line">
            {matches.map((m) => (
              <li key={m.id}>
                <button type="button" data-testid="lookup-match" className="flex w-full items-center gap-3 px-4 py-3 text-left hover:bg-paper" onClick={() => verify({ reservationId: m.id })}>
                  <span className="w-14 font-display text-xl font-extrabold tabular">{m.time}</span>
                  <span className="min-w-0 flex-1"><span className="block truncate font-semibold">{m.customerName}</span><span className="block text-[14px] text-ink-soft">{m.partySize} guests, {m.reference}</span></span>
                  <StatusBadge status={m.status} />
                </button>
              </li>
            ))}
          </ul>
        ))}
        <details>
          <summary className="cursor-pointer font-semibold text-ink-soft select-none">Paste a ticket link or code</summary>
          <form className="mt-2 flex gap-2" onSubmit={(e) => { e.preventDefault(); if (code.trim()) void verify({ code: code.trim().slice(0, 400) }); }}>
            <input className={inputClass} value={code} onChange={(e) => setCode(e.target.value)} placeholder="Ticket link" aria-label="Ticket link or code" autoComplete="off" />
            <Button type="submit" variant="quiet" disabled={busy || !code.trim()}>Verify</Button>
          </form>
        </details>
      </Card>
    </div>
  );
}
